/* 临时校验脚本：截取门户大屏部署站点与「成交面积段结构」面板区域 */
const fs = require('fs')
const path = require('path')
const { chromium } = require('D:/repository/门户/node_modules/playwright')
const { PNG } = require('D:/repository/门户/node_modules/pngjs')

const mode = process.argv[2] || 'before'
const OUT = path.resolve('D:/repository/门户/test-results/mm-area-bar')
fs.mkdirSync(OUT, { recursive: true })
// 截图里红框标出的「成交面积段结构」面板区域（1920x1080 设计稿）
const PANEL = { x: 1272, y: 385, width: 640, height: 402 }

;(async () => {
  const browser = await chromium.launch({ headless: true })
  const page = await browser.newPage({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 1 })
  const errors = []
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message))
  await page.goto('http://127.0.0.1:8092/index.html#/market-monitor', { waitUntil: 'domcontentloaded', timeout: 60000 })
  await page.evaluate(() => document.fonts.ready).catch(() => {})
  await page.waitForTimeout(2600)
  await page.screenshot({ path: path.join(OUT, mode + '-full.png'), animations: 'disabled' })
  await page.screenshot({ path: path.join(OUT, mode + '-panel.png'), clip: PANEL, animations: 'disabled' })
  const canvasCount = await page.locator('canvas').count()
  console.log(JSON.stringify({ mode, canvasCount, errors, panel: PANEL }))
  await browser.close()
})().catch(e => { console.error(e); process.exit(1) })

