const fs = require('fs')
const path = require('path')
const { PNG } = require('D:/repository/门户/node_modules/pngjs')
const pm = require('D:/repository/门户/node_modules/pixelmatch')
const OUT = path.resolve('D:/repository/门户/test-results/mm-area-bar')
const A = PNG.sync.read(fs.readFileSync(path.join(OUT, 'before-full.png')))
const B = PNG.sync.read(fs.readFileSync(path.join(OUT, 'after-full.png')))
const PANEL = { x: 1272, y: 385, width: 640, height: 402 }
let inside = 0, outside = 0, total = 0
for (let y = 0; y < Math.min(A.height, B.height); y++) {
  for (let x = 0; x < Math.min(A.width, B.width); x++) {
    const i = (y * A.width + x) * 4
    const d = Math.abs(A.data[i] - B.data[i]) + Math.abs(A.data[i + 1] - B.data[i + 1]) + Math.abs(A.data[i + 2] - B.data[i + 2])
    if (d > 12) {
      total++
      if (x >= PANEL.x && x < PANEL.x + PANEL.width && y >= PANEL.y && y < PANEL.y + PANEL.height) inside++
      else outside++
    }
  }
}
console.log(JSON.stringify({ changedPixels: total, insidePanel: inside, outsidePanel: outside }))
